import cv2
import numpy as np
from typing import List, Tuple
import os

from src.utils.image_utils import save_image

# This file contains standalone utility functions for detecting color checker patches.
# The logic is adapted from the ColorCorrectionPipeline to be reusable.

def _save_debug_image(output_dir, name, image, step_counter):
    if output_dir and image is not None:
        path = os.path.join(output_dir, f"{step_counter:02d}_{name}.png")
        save_image(path, image)
        return path
    return None

def _detect_patches_simple_grid(image: np.ndarray, name: str, debug_info: dict) -> Tuple[List[np.ndarray], List[Tuple[int, int, int, int]]]:
    """
    Extracts patches using a simple, hardcoded 4x6 grid and sampling the center of each cell.
    """
    h, w, _ = image.shape
    ROWS, COLS = 4, 6
    patch_h, patch_w = h / ROWS, w / COLS

    patches = []
    final_coords = []

    if patch_h <= 1 or patch_w <= 1:
        return [], []

    for r in range(ROWS):
        for c in range(COLS):
            center_x = int(patch_w * (c + 0.5))
            center_y = int(patch_h * (r + 0.5))

            sample_h = int(patch_h * 0.5)
            sample_w = int(patch_w * 0.5)

            y1 = center_y - sample_h // 2
            y2 = center_y + sample_h // 2
            x1 = center_x - sample_w // 2
            x2 = center_x + sample_w // 2

            patch_roi = image[y1:y2, x1:x2]

            if patch_roi.size > 0:
                patches.append(patch_roi)
                final_coords.append((x1, y1, x2, y2))

    if len(patches) == 24 and debug_info["debug_mode"]:
        output_vis_grid = image.copy()
        for (x1, y1, x2, y2) in final_coords:
            cv2.rectangle(output_vis_grid, (x1, y1), (x2, y2), (255, 255, 255), 2)
        _save_debug_image(debug_info["output_dir"], f"patch_detect_simple_grid_success_{name}", output_vis_grid, debug_info["step_counter"])
        debug_info["step_counter"] += 1

    return (patches, final_coords) if len(patches) == 24 else ([], [])

def _detect_patches_grid_based(image: np.ndarray, name: str, debug_info: dict) -> Tuple[List[np.ndarray], List[Tuple[int, int, int, int]]]:
    try:
        from src.color_correction.patch_detector import PatchExtractor
        extractor = PatchExtractor(image)
        patch_infos = extractor.detect_patches(adaptive=True)
        if patch_infos and len(patch_infos) >= 18:
            patches, final_coords = [], []
            for info in patch_infos:
                x, y, w, h = info.bounding_box
                patch_img = image[y : y + h, x : x + w]
                if patch_img.size > 0:
                    patches.append(patch_img)
                    final_coords.append((x, y, x + w, y + h))
            if len(patches) >= 18:
                if debug_info["debug_mode"]:
                    vis_img = extractor.visualize_patches(patch_infos, show_numbers=True)
                    _save_debug_image(debug_info["output_dir"], f"patch_detect_grid_based_success_{name}", vis_img, debug_info["step_counter"])
                    debug_info["step_counter"] += 1
                return patches, final_coords
    except Exception:
        pass
    return [], []

def detect_patches_from_image(image: np.ndarray, name: str = "validation", debug_mode: bool = False, output_dir: str = None) -> dict:
    """
    Detects patches using a multi-stage approach with fallbacks.
    Returns a dictionary with 'patches', 'patch_coords', and 'detection_method'.
    """
    if image is None or image.size == 0:
        return {"patches": [], "patch_coords": [], "detection_method": "error"}

    debug_info = {"debug_mode": debug_mode, "output_dir": output_dir, "step_counter": 0}

    # --- Method 1: Simple Grid Sampling (Primary) ---
    patches, final_coords = _detect_patches_simple_grid(image, name, debug_info)
    if patches:
        return {"patches": patches, "patch_coords": final_coords, "detection_method": "simple_grid"}

    # --- Method 2: Grid-based detection (Fallback 1) ---
    patches, final_coords = _detect_patches_grid_based(image, name, debug_info)
    if patches:
        return {"patches": patches, "patch_coords": final_coords, "detection_method": "grid_based"}

    # Note: Mask-based and BBox-based methods from the original pipeline could be added here for more robustness if needed.

    return {"patches": [], "patch_coords": [], "detection_method": "failed"}

